"""LLM-as-a-judge evaluation for text simulations.

Runs two optional judge calls: success-criteria evaluation (Call 1) and
quality-dimension scoring (Call 2). Partial failures are captured on
``LlmJudgeResults`` rather than raising.
"""

import asyncio
import json
from typing import Any, Dict, List, Optional, Tuple

import structlog

from rasa.builder.copilot.mcp_server.constants import (
    LLM_MESSAGE_CONTENT,
    LLM_ROLE,
    LLM_ROLE_USER,
    SIM_EVAL_LLM_MAX_ATTEMPTS,
    SIM_EVAL_RETRY_BACKOFF_FACTOR,
)
from rasa.builder.copilot.mcp_server.prompts.prompt_loader import (
    copilot_jinja_env,
    get_evaluation_criteria_judge_prompt_template,
    get_evaluation_metrics_judge_prompt_template,
)
from rasa.builder.copilot.mcp_server.tools.event_ledger import build_event_ledger
from rasa.builder.copilot.mcp_server.tools.llm_judge_models import (
    DEFAULT_BINARY_METRIC_KEYS,
    DEFAULT_SCALE_METRIC_KEYS,
    BinaryMetricResult,
    CriterionResult,
    LlmJudgeResults,
    ScaleMetricResult,
)
from rasa.builder.copilot.mcp_server.tools.scenario import Scenario
from rasa.shared.core.events import Event
from rasa.shared.providers.llm.llm_client import LLMClient
from rasa.shared.utils.llm import supports_json_response_format

structlogger = structlog.get_logger()

# ``DEFAULT_SCALE_METRIC_KEYS`` / ``DEFAULT_BINARY_METRIC_KEYS`` are defined in
# ``llm_judge_models`` (alongside ``bot_quality``, which depends on them) and
# re-exported here for callers that import the built-in metric keys from this
# module. They give reports/aggregations a stable display order, and customers
# can still add metrics by editing only the prompt and its JSON schema — the
# validator enforces shape, not membership.
__all__ = ["DEFAULT_SCALE_METRIC_KEYS", "DEFAULT_BINARY_METRIC_KEYS"]

# Judge prompts produce structured JSON that can exceed the default 256-token
# cap injected by ``mcp_base_agent.DEFAULT_LLM_CONFIG``.
TEXT_JUDGE_MAX_TOKENS = 4000


async def run_llm_as_a_judge(
    scenario: Scenario,
    turns: List[Dict[str, Any]],
    evaluator_client: LLMClient,
    *,
    criteria_prompt_template: str = get_evaluation_criteria_judge_prompt_template(),
    metrics_prompt_template: str = get_evaluation_metrics_judge_prompt_template(),
    timeout_s: Optional[float] = None,
    events: Optional[List[Event]] = None,
    conversation_id: Optional[str] = None,
) -> LlmJudgeResults:
    """Run the text judge (criteria + quality dimensions).

    Does not raise on partial failure — errors are captured on the
    returned ``LlmJudgeResults``.

    Args:
        scenario: Parsed scenario as a ``Scenario`` model instance.
        turns: Simulated conversation turns (user + bot lines).
        evaluator_client: LLM client used for judge completions.
        criteria_prompt_template: Jinja2 template for success criteria evaluation.
        metrics_prompt_template: Jinja2 template for quality metrics evaluation.
        timeout_s: Per-LLM-call wall-clock timeout for each judge call.
        events: Optional typed tracker events, e.g.
            ``deserialise_events(tracker["events"])`` (the same typed events the
            assertion engine consumes — the runner parses them once upstream).
            When provided, a curated, turn-anchored event ledger is built and
            passed to the criteria judge only (Call 1) as behind-the-scenes
            ground truth for hallucination detection. The dimensions judge
            (Call 2) intentionally never sees it — quality scoring is about
            the user-visible conversation. See
            :mod:`rasa.builder.copilot.mcp_server.tools.event_ledger`.
        conversation_id: Rasa conversation (sender) id for LLM debug logs.
    """
    if not turns:
        raise ValueError("conversation has no turns to evaluate")

    transcript = build_simulation_transcript(turns)
    if not transcript:
        raise ValueError(
            "conversation transcript is empty (bot returned no responses)",
        )

    event_ledger = build_event_ledger(events) if events else ""

    crit_coro = (
        _evaluate_criteria_with_llm(
            evaluator_client,
            transcript=transcript,
            criteria=scenario.goals.criteria,
            prompt_template=criteria_prompt_template,
            timeout_s=timeout_s,
            event_ledger=event_ledger,
            conversation_id=conversation_id,
        )
        if scenario.goals.criteria
        else _empty_criteria_result()
    )
    dim_coro = _evaluate_metrics_with_llm(
        evaluator_client,
        transcript=transcript,
        prompt_template=metrics_prompt_template,
        timeout_s=timeout_s,
        conversation_id=conversation_id,
    )

    crit_out, dim_out = await asyncio.gather(
        crit_coro,
        dim_coro,
        return_exceptions=True,
    )

    result = LlmJudgeResults()

    if isinstance(crit_out, BaseException):
        result.criteria.error = _format_judge_exception(crit_out)
    else:
        result.criteria.results = crit_out

    if isinstance(dim_out, BaseException):
        result.metrics.error = _format_judge_exception(dim_out)
    else:
        (
            result.metrics.scale_metrics,
            result.metrics.binary_metrics,
            result.metrics.summary,
        ) = dim_out

    return result


def _parse_judge_json(raw: str) -> Dict[str, Any]:
    """Parse the judge LLM response into a dict."""
    if not raw:
        raise ValueError("model returned an empty response")
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            return obj
    except json.JSONDecodeError:
        pass
    start = raw.find("{")
    if start >= 0:
        try:
            obj, _ = json.JSONDecoder().raw_decode(raw[start:])
            if isinstance(obj, dict):
                return obj
        except json.JSONDecodeError:
            pass
    raise ValueError("could not parse JSON from model response")


def build_simulation_transcript(turns: List[Dict[str, Any]]) -> str:
    """Build a plain-text transcript from simulated conversation turns.

    Each bot utterance in a turn is rendered on its own ``Bot:`` line, so a
    turn with multiple bot messages never produces an unlabeled continuation
    line that the judge could misread as part of the previous message.
    """
    blocks: List[str] = []
    for turn in turns:
        bot_messages = turn.get("bot")
        if not bot_messages:
            continue
        lines = [f"User: {turn['user']}"]
        lines.extend(f"Bot: {message}" for message in bot_messages)
        blocks.append("\n".join(lines))
    return "\n".join(blocks)


def _validate_criteria_payload(
    parsed: Dict[str, Any],
    expected_n: int,
) -> Optional[str]:
    """Return an error message when criteria JSON fails structural validation."""
    if expected_n == 0:
        return None
    crits = parsed.get("criteria")
    if not isinstance(crits, list):
        return "'criteria' must be a JSON array"
    if len(crits) != expected_n:
        return f"expected {expected_n} criteria entries, got {len(crits)}"
    seen: set[int] = set()
    for item in crits:
        if not isinstance(item, dict):
            return "each criterion entry must be an object"
        idx_any = item.get("criterion_index")
        try:
            idx = int(idx_any)
        except (TypeError, ValueError):
            return "invalid criterion_index (must be a positive integer)"
        if idx < 1 or idx > expected_n:
            return f"criterion_index {idx} out of range 1..{expected_n}"
        if idx in seen:
            return f"duplicate criterion_index {idx}"
        seen.add(idx)
        # Require an explicit boolean verdict. Without this, an omitted
        # ``passed`` coerces to ``False`` and a judge that simply forgot the
        # field looks like a deliberate fail; rejecting it triggers a retry
        # instead (parity with ``binary_metrics``).
        if not isinstance(item.get("passed"), bool):
            return f"criterion_index {idx} passed must be a JSON boolean"
    return None


def _normalize_criteria_rows(
    parsed: Dict[str, Any],
    yaml_criteria: List[str],
) -> List[CriterionResult]:
    """Map validated criteria JSON onto ``CriterionResult`` rows."""
    by_index = {int(item["criterion_index"]): item for item in parsed["criteria"]}
    rows: List[CriterionResult] = []
    for i, expected_text in enumerate(yaml_criteria, start=1):
        raw_item = by_index[i]
        echo_any = raw_item.get("criterion_text")
        if isinstance(echo_any, str) and echo_any.strip():
            criterion_label = echo_any.strip()
        else:
            criterion_label = expected_text
        rows.append(
            CriterionResult(
                criterion=criterion_label,
                passed=raw_item["passed"],
                reasoning=str(raw_item.get("reasoning", "")),
            )
        )
    return rows


def _validate_scale_metric_entry(key: str, entry: Any) -> Optional[str]:
    """Validate one ``scale_metrics`` entry: ``{score: int 1-5, reasoning: str}``."""
    if not isinstance(entry, dict):
        return f"scale_metrics.{key} must be an object"
    raw_score = entry.get("score")
    if isinstance(raw_score, bool) or raw_score is None:
        return f"invalid score for scale_metrics.{key} (not a number)"
    try:
        if isinstance(raw_score, float) and not raw_score.is_integer():
            return f"scale_metrics.{key} score must be an integer 1–5"
        score_i = int(raw_score)
    except (TypeError, ValueError):
        return f"invalid score type for scale_metrics.{key} (not a number)"
    if score_i < 1 or score_i > 5:
        return f"scale_metrics.{key} score must be 1–5, got {score_i}"
    return None


def _validate_binary_metric_entry(key: str, entry: Any) -> Optional[str]:
    """Validate one ``binary_metrics`` entry: ``{passed: bool, reasoning: str}``."""
    if not isinstance(entry, dict):
        return f"binary_metrics.{key} must be an object"
    raw = entry.get("passed")
    if not isinstance(raw, bool):
        return f"binary_metrics.{key} passed must be a JSON boolean"
    return None


def _validate_dimensions_payload(parsed: Dict[str, Any]) -> Optional[str]:
    """Structural validation for the metrics judge payload.

    Accepts ``binary_metrics`` and ``scale_metrics`` groups (either may be
    empty or absent, but at least one metric overall must be present so a
    judge that returned nothing is rejected). Keys are not constrained —
    customers can extend the rubric by editing only the prompt and its
    JSON schema.
    """
    scale = parsed.get("scale_metrics")
    binary = parsed.get("binary_metrics")
    if scale is None:
        scale = {}
    if binary is None:
        binary = {}
    if not isinstance(scale, dict):
        return "'scale_metrics' must be an object"
    if not isinstance(binary, dict):
        return "'binary_metrics' must be an object"
    if not scale and not binary:
        return "metrics payload must contain at least one metric"

    seen: set[str] = set()
    for key, entry in scale.items():
        if not isinstance(key, str) or not key.strip():
            return "invalid scale_metrics key (must be a non-empty string)"
        if key in seen:
            return "duplicate metric key across groups"
        seen.add(key)
        err = _validate_scale_metric_entry(key, entry)
        if err is not None:
            return err

    for key, entry in binary.items():
        if not isinstance(key, str) or not key.strip():
            return "invalid binary_metrics key (must be a non-empty string)"
        if key in seen:
            return "duplicate metric key across groups"
        seen.add(key)
        err = _validate_binary_metric_entry(key, entry)
        if err is not None:
            return err

    return None


def _normalize_dimensions_payload(
    parsed: Dict[str, Any],
) -> Tuple[Dict[str, ScaleMetricResult], Dict[str, BinaryMetricResult], Optional[str]]:
    """Map validated metrics JSON onto result objects and overall summary."""
    scale_raw = parsed.get("scale_metrics") or {}
    binary_raw = parsed.get("binary_metrics") or {}

    scale_results: Dict[str, ScaleMetricResult] = {}
    for key, entry in scale_raw.items():
        r = entry.get("reasoning", "")
        reasoning = r.strip() if isinstance(r, str) else str(r)
        scale_results[key] = ScaleMetricResult(
            score=int(entry["score"]),
            reasoning=reasoning,
        )

    binary_results: Dict[str, BinaryMetricResult] = {}
    for key, entry in binary_raw.items():
        r = entry.get("reasoning", "")
        reasoning = r.strip() if isinstance(r, str) else str(r)
        binary_results[key] = BinaryMetricResult(
            passed=bool(entry["passed"]),
            reasoning=reasoning,
        )

    summary_any = parsed.get("summary")
    summary = summary_any.strip() if isinstance(summary_any, str) else None
    return scale_results, binary_results, summary or None


async def _judge_acompletion(
    llm_client: LLMClient,
    messages: List[Dict[str, str]],
    timeout_s: Optional[float],
    *,
    conversation_id: Optional[str] = None,
) -> str:
    """Run one judge LLM completion with JSON mode when supported."""
    extra_kwargs: Dict[str, Any] = {
        "max_completion_tokens": TEXT_JUDGE_MAX_TOKENS,
    }
    json_mode_supported = supports_json_response_format(llm_client)
    structlogger.debug(
        "rasa.evaluation.judge.json_mode",
        conversation_id=conversation_id,
        supported=json_mode_supported,
        model=(llm_client.config or {}).get("model"),
    )
    if json_mode_supported:
        extra_kwargs["response_format"] = {"type": "json_object"}

    completion_coro = llm_client.acompletion(messages, **extra_kwargs)
    if timeout_s is not None:
        response = await asyncio.wait_for(completion_coro, timeout=timeout_s)
    else:
        response = await completion_coro
    return response.choices[0].strip()


async def _evaluate_criteria_with_llm(
    llm_client: LLMClient,
    *,
    transcript: str,
    criteria: List[str],
    prompt_template: str,
    timeout_s: Optional[float],
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
    event_ledger: str = "",
    conversation_id: Optional[str] = None,
) -> List[CriterionResult]:
    """Criteria judge (Call 1). Retries on parse/validation errors.

    When ``event_ledger`` is non-empty, the prompt's ``{% if event_ledger %}``
    block renders the behind-the-scenes timeline so the judge can detect
    hallucinated outcomes (bot claims an action it never actually performed).
    """
    criteria_text = "\n".join(f"{i + 1}. {c}" for i, c in enumerate(criteria))
    prompt = (
        copilot_jinja_env()
        .from_string(prompt_template)
        .render(
            criteria_text=criteria_text,
            transcript=transcript,
            event_ledger=event_ledger,
        )
    )
    messages = [{LLM_ROLE: LLM_ROLE_USER, LLM_MESSAGE_CONTENT: prompt}]
    expected_n = len(criteria)
    structlogger.debug(
        "rasa.evaluation.criteria.prompt",
        conversation_id=conversation_id,
        messages=messages,
        criteria_count=expected_n,
    )

    last_error: Exception = ValueError("no judge attempts succeeded")
    for attempt in range(1, max_attempts + 1):
        try:
            raw = await _judge_acompletion(
                llm_client, messages, timeout_s, conversation_id=conversation_id
            )
            parsed = _parse_judge_json(raw)
            verr = _validate_criteria_payload(parsed, expected_n)
            if verr is None:
                return _normalize_criteria_rows(parsed, criteria)
            last_error = ValueError(verr)
            structlogger.warning(
                "rasa.evaluation.criteria.validation_retry",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error_type=last_error.__class__.__name__,
                error=str(last_error),
            )
        except Exception as exc:
            last_error = exc
            structlogger.warning(
                "rasa.evaluation.criteria.retry",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error_type=exc.__class__.__name__,
                error=repr(exc),
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.evaluation.criteria.failed",
        conversation_id=conversation_id,
        max_attempts=max_attempts,
        error_type=last_error.__class__.__name__,
        error=repr(last_error),
    )
    raise last_error


async def _evaluate_metrics_with_llm(
    llm_client: LLMClient,
    *,
    transcript: str,
    prompt_template: str,
    timeout_s: Optional[float],
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
    conversation_id: Optional[str] = None,
) -> Tuple[
    Dict[str, ScaleMetricResult],
    Dict[str, BinaryMetricResult],
    Optional[str],
]:
    """Quality metrics judge (Call 2). Retries on parse/validation errors."""
    prompt = (
        copilot_jinja_env().from_string(prompt_template).render(transcript=transcript)
    )
    messages = [{LLM_ROLE: LLM_ROLE_USER, LLM_MESSAGE_CONTENT: prompt}]
    structlogger.debug(
        "rasa.evaluation.metrics.prompt",
        conversation_id=conversation_id,
        messages=messages,
    )

    last_error: Exception = ValueError("no judge attempts succeeded")
    for attempt in range(1, max_attempts + 1):
        try:
            raw = await _judge_acompletion(
                llm_client, messages, timeout_s, conversation_id=conversation_id
            )
            parsed = _parse_judge_json(raw)
            derr = _validate_dimensions_payload(parsed)
            if derr is None:
                return _normalize_dimensions_payload(parsed)
            last_error = ValueError(derr)
            structlogger.warning(
                "rasa.evaluation.metrics.validation_retry",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error_type=last_error.__class__.__name__,
                error=str(last_error),
            )
        except Exception as exc:
            last_error = exc
            structlogger.warning(
                "rasa.evaluation.metrics.retry",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error_type=exc.__class__.__name__,
                error=repr(exc),
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.evaluation.metrics.failed",
        conversation_id=conversation_id,
        max_attempts=max_attempts,
        error_type=last_error.__class__.__name__,
        error=repr(last_error),
    )
    raise last_error


async def _empty_criteria_result() -> List[CriterionResult]:
    """No-op coroutine used when a scenario defines no success criteria."""
    return []


def _format_judge_exception(exc: BaseException) -> str:
    """Compact error text stored on ``LlmJudgeResults``.

    Includes ``ValueError`` messages raised by our structural validators
    (fixed-format strings with no embedded model output). Other exception
    types surface as the class name only so transcript/response snippets
    cannot leak via ``str(exc)``.
    """
    name = exc.__class__.__name__
    if isinstance(exc, ValueError):
        msg = str(exc).strip()
        if msg:
            return f"{name}: {msg}"
    return name
